   [178]={next_id=179, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你上前一步，扶着她重新躺下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [179]={next_id=180, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉，快去倒水。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [180]={next_id=181, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="好。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉应了一声，跑到厨房倒了两杯白开水，小心翼翼端到你面前。你接过，喝了一口。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="入口一股奇怪的味道，说不清是什么。淡淡的颗粒感顺着喉咙进入胃里，让你忍不住轻轻咳嗽起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="咳咳咳。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [184]={next_id=185, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="（这水里好像有沙子……）", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [185]={next_id=186, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="恩人，看你的表情是第一次喝这里的水吧。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们这里条件恶劣，水源全是从地底深处打上来的地下水，所以杂质会比较多。我们喝了十几年，都已经习惯了。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [187]={next_id=188, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你看着床头柜上的一张照片。照片里，一个男人搂着一个女人，女人怀里抱着一个襁褓。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [188]={next_id=189, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="男人笑得很灿烂，露出一口整齐的白牙。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [189]={next_id=190, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而照片旁边，放着一只小小的香炉，香灰已经积了厚厚一层。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [190]={next_id=191, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="照片里的这位是……米拉的爸爸？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [191]={next_id=192, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉母亲的眼神黯淡了下来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [192]={next_id=193, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……矿难，走了快一年了。连尸首都没找到……", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [193]={next_id=194, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉站在床边，低着头，两只小手攥着裙角。她没有哭，但你看到她的肩膀在微微发抖。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [194]={next_id=195, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你沉默了几秒。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [195]={next_id=196, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="能和我说说这里发生的事情吗？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [196]={next_id=197, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉抬起头，看了你一眼，又看了看妈妈，随后深吸了一口气，像是鼓起了很大的勇气。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [197]={next_id=198, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="爸爸说过，如果有一天遇到外面来的、愿意听的好人，就让我说出去……", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [198]={next_id=199, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="很久以前，这里不叫大空洞，叫格拉村。村子底下有好多的源晶，大家自己挖，自己背去城里卖。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [199]={next_id=200, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然辛苦，但大家都有饭吃，有房子住，日子过得挺好的。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [200]={next_id=201, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="原来还有这种事。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [201]={next_id=202, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你看向蛰吻，见她点点头，显然是知道这件事情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [202]={next_id=203, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来，凯瑞公司来了。他们跟村子里的人说，以后由他们来承包矿，给村子里的人修路、建学校、发工资。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [203]={next_id=204, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="村子里的人一合计，自己挖太慢了，不知道要挖到猴年马月。凯瑞公司的条件这么好，不如就答应了吧。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [204]={next_id=205, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="刚开始那几年，确实挺好的。路修了，学校建了，每个月还真发钱。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [205]={next_id=206, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可是后来……", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [206]={next_id=207, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声音越来越低，隐隐带着啜泣。米拉的妈妈把米拉搂进怀里，温柔的抚摸着她的脑袋。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [207]={next_id=208, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来凯瑞公司说，矿脉比预计的浅，成本比预计的高，答应的条件要取消一部分。由于收入减少，大家日子开始不好过起来。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [208]={next_id=209, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="某天，凯瑞公司说想要收购我们的土地所有权，报酬比之前更加丰厚。当时快走投无路的大家最终还是同意了凯瑞公司的交易。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [209]={next_id=210, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可后来，当最后一个村民将自己的土地卖给凯瑞公司后，他突然要我们全都搬走……我们不搬，他们就断水断电，还雇了打手。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [210]={next_id=211, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最后大家没办法，搬到了这里。但他们说，这里还是凯瑞公司的地，要住就得签合同。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [211]={next_id=212, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可我们都知道，一旦签了合同，就相当于欠了公司的债。而欠了债……就得去公司当矿工，赚钱还债。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [212]={next_id=213, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你叹了口气，知道了这里的居民为什么会这么穷。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [213]={next_id=214, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这就像掉进了一个大坑里，怎么爬都爬不出来。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [214]={next_id=215, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来这里的矿挖完了，公司的人走了不少。我们曾以为，凯瑞公司的人走后，村子本来应该还给我们的，但……他们不给。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [215]={next_id=216, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哪怕是空在这里，废弃掉，也不会还给我们这些“矿民”。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [216]={next_id=217, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻坐在旁边，没有说话。她的表情依然平静，但你知道她在听，每一个字都在听。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [217]={next_id=218, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="本来以为就这样了，大家认命了。但是十年前。凯瑞公司的人又回来了，他们说大空洞地底下又发现了新的源晶矿，要重新掌握这里的开采权。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [218]={next_id=219, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大家不同意，村长带着大家去公司门口说理。可凯瑞公司不知许下了什么好处，竟然让组特站在了凯瑞公司那一边。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [219]={next_id=220, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="或许是因为艾朵……她是组特的妹妹，是米拉儿时的玩伴。可后来艾朵生病了，大空洞里没有人能治好她，唯有凯瑞公司有办法……", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [220]={next_id=221, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最后，在组特的劝说下，大家又一次妥协了。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [221]={next_id=222, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="（组特……是当时凯瑞公司安保队那个领头的吗。）", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [222]={next_id=223, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来……后来我家那位和工友们去给凯瑞公司挖矿，就再也没回来……", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [223]={next_id=224, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当时闹得很凶，凯瑞公司也没给个说法。拉文他们就是在那个时候站出来的，带着矿工们跟公司谈判。", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [224]={next_id=225, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="再后来……", msg_color="", msg_size=0, talker="米拉妈妈", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [225]={next_id=226, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="再后来，余烬的哥哥姐姐们来了。他们帮我们跟公司谈判，帮我们守夜，怕公司的人半夜来搞破坏。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [226]={next_id=227, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果不是余烬，我们可能已经被赶出大空洞了。", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [227]={next_id=228, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉说完，低着头，两只手绞在一起。米拉母亲躺在床上，无声地流着眼泪。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [228]={next_id=229, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们就没想过要逃出去？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [229]={next_id=230, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="逃？怎么逃？", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [230]={next_id=231, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="离这里最近的赞布拉城要走数百公里的路，没有飞行器的话不知道要走多久，而且一路上还有各种凶猛的异变体……", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [231]={next_id=232, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="房间里安静了很久。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [232]={next_id=233, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大哥哥，你说村长他们当初错了吗？", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
