   [235]={next_id=236, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="照片里的男人还在笑。他大概永远不会知道，他的妻子和女儿，正在这片他拼了命想守护的土地上，艰难地活着。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
