   [241]={next_id=242, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="夜晚，凯瑞公司顶层宴会厅。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="70", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [242]={next_id=243, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="与底层破败的矿区截然不同，这里灯火璀璨，冷白色的顶灯照亮整间奢华包厢。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [243]={next_id=244, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大理石地面光洁如镜，墙面镶嵌昂贵的暗金饰板，空气中弥漫着昂贵雪茄与高级红酒交织的味道，处处透着上位者独有的傲慢与压迫感。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [244]={next_id=245, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="偌大的包厢内没有多余的宾客，整场晚宴自始至终只为蛰吻一人而设。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [245]={next_id=246, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你陪同蛰吻走入包厢。蛰吻没有多余的客套，径直坐到了一旁的沙发上，而你则站在她的身侧。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [246]={next_id=247, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="正对面的沙发上，坐着一名西装革履、体态略显臃肿的中年男人——凯瑞公司现任总裁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [247]={next_id=248, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="男人指尖夹着一支雪茄，慵懒地靠在椅背之上，目光自上而下审视着你们，眼底带着商人独有的算计与轻蔑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [248]={next_id=249, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="包厢两侧暗处，十几名全副武装的安保队员静默伫立，枪械紧贴身侧，无形的杀气笼罩全场。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [249]={next_id=250, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="门外走廊、楼下出入口、甚至整栋大楼外围，早已被凯瑞的安保部队层层封锁，密不透风。摆明了，这就是一场带有目的陷阱。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [250]={next_id=251, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁吐出一口淡薄的烟圈，烟气缓缓升腾，消散在冰冷的空气里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [251]={next_id=252, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻家主。久仰。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [252]={next_id=253, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他抬了抬夹着雪茄的手，算是致意，目光淡淡地扫过你。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [253]={next_id=254, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不过我记得，请帖上只写了一个人的名字。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [254]={next_id=255, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻没有接他的话。她端起面前的茶杯，低头看了一眼茶汤的颜色，又放下了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [255]={next_id=256, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="总裁特意把整栋楼清空，就为了请我喝一杯茶？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [256]={next_id=257, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁嘴角的笑意没有变，但眼底多了一层意味不明的东西。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [257]={next_id=258, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="清空？蛰吻家主说笑了。只不过是今天让员工提前下班了而已。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [258]={next_id=259, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那楼下那些持枪的人，也是“提前下班”的一部分？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [259]={next_id=260, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁轻笑一声，将雪茄搁在烟灰缸边缘，身子微微前倾，像一头睁开眼的猛兽。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [260]={next_id=261, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻，你知道我为什么请你来吗？", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [261]={next_id=262, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="洗耳恭听。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [262]={next_id=263, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大空洞这个地方，说大不大，说小不小。凯瑞公司在这里经营了十几年，该铺的路铺了，该清的人清了。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [263]={next_id=264, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他顿了顿，手指在扶手上轻轻敲了两下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [264]={next_id=265, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但这两年，有人开始在我不点头的地方……动土了。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [265]={next_id=266, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻像是没听到他话里的讥讽，表情依旧平静淡然。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [266]={next_id=267, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="余烬保护的是大空洞的居民。他们交不起保护费，请不起佣兵，甚至连看病都要看凯瑞的脸色。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [267]={next_id=268, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞公司不愿意管的地方，余烬来管。这算不上“动土”，只是填补空白。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [268]={next_id=269, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁的笑意终于淡了下去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [269]={next_id=270, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="填补空白。好一个填补空白。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [270]={next_id=271, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他重新靠回椅背，声音慢了下来，每个字都像在称重量。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [271]={next_id=272, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻，你是个聪明人，我不跟你绕弯子。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [272]={next_id=273, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞公司在大空洞，图的是地下的矿产。你图什么，我不关心。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [273]={next_id=274, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但有一条底线——我的事情，你们别来插手。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [274]={next_id=275, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="守住你现在那一亩三分地，我当没看见。越界了——", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [275]={next_id=276, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他没有把话说完，只是将雪茄重新叼回嘴里，深深吸了一口。烟雾在两人之间扩散开来，模糊了彼此的表情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [276]={next_id=277, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻安静地听完，没有立刻反驳，也没有动怒。她只是端起那杯刚才放下的茶，轻轻吹了吹，抿了一口。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [277]={next_id=278, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你知道余烬的成员，都是什么人吗？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [278]={next_id=279, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是被抛弃的孩子，是被压垮的矿工，是被你们凯瑞公司所践踏的人。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [279]={next_id=280, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你问我图什么。我不图矿，不图钱，不图地盘。我图的是——那些人不用再跪着活。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [280]={next_id=281, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这一点，凯瑞公司给不了。所以，余烬不会退。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [281]={next_id=282, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="包厢内的温度瞬间降至冰点，两侧的安保队员瞬间绷紧身体，手掌不约而同按在了腰间的枪械上，杀意暴涨。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [282]={next_id=283, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁的脸色彻底沉了下来，阴鸷的眼底翻涌着怒意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [283]={next_id=284, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这么说来，蛰吻家主是打算执意与我凯瑞公司为敌？", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [284]={next_id=285, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你真以为凭借那一群乌合之众，有资格和我作对？", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [285]={next_id=286, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="现在整栋大楼，乃至方圆百米，全部被我的人团团围住。只要我一声令下，你们今天根本走不出这扇门。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [286]={next_id=287, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="面对赤裸裸的威胁，蛰吻脸上依旧不见丝毫慌乱。她唇角微扬，勾起一抹冷淡的笑意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [287]={next_id=288, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你以为，我会毫无防备，孤身闯入你的地盘？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [288]={next_id=289, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="话音落下，她微微侧首，薄唇轻启，吹出一声清亮短促的口哨。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [289]={next_id=290, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="咻——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [290]={next_id=291, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="清脆的哨音穿透厚重的包厢墙壁，穿透层层走廊，响彻整栋大楼。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [291]={next_id=292, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="下一瞬。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [292]={next_id=293, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="楼下、走廊尽头、天台方向，四面八方接连响起此起彼伏的回应哨声，长短交错，井然有序。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [293]={next_id=294, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哨声沉稳、密集，无声地宣告着一件让奥洛斯浑身发冷的事实——在他自以为绝对掌控、重兵封锁的地盘里，余烬的人早已悄无声息渗透进来，遍布每一个角落。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [294]={next_id=295, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的安保部队人数确实很多，但……余烬的实力超过你的想象。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [295]={next_id=296, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻一脚将面前的桌子踢翻，桌上的茶水顺势飞向凯瑞总裁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [296]={next_id=297, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁本能的想要伸手去挡，但比茶水还快的是蛰吻以一个刁钻的角度踢来的一脚。她将凯瑞总裁踹翻在地，高跟鞋狠狠的踩在他的脸上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [297]={next_id=298, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="四周的守卫愣了片刻，他们没想到蛰吻会动手的这么果决，随后反应了过来，拿出武器准备上前将你们拿下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [298]={next_id=299, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但就在下一刻，守卫们的惨叫声响起。你以一个极快的速度，在蛰吻动手的瞬间，便将这些守卫们放倒在地。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [299]={next_id=300, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="现在，攻守易形了。只要我想，就可以轻松要了你的命。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [300]={next_id=301, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞总裁死死盯着蛰吻，胸腔剧烈起伏了几次。最终，他松开攥紧的拳头，像是在把什么咽回肚子里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [301]={next_id=302, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是你赢了……", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [302]={next_id=303, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻嘴角露出一个弧度。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [303]={next_id=304, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="余烬不会向任何人妥协，我们会尽全力守护我们的“家”。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [304]={next_id=305, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻松开脚，凯瑞总裁狼狈地站起身，拿起搭在椅背上的外套，头也不回地朝门口走去。经过你们身侧时，他停了一瞬，没有看你们，只是丢下一句——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [305]={next_id=306, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="希望你不会为了今天的决定而后悔。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [306]={next_id=307, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="厚重的包厢门被保镖从外侧重重关上，沉闷的撞击声，象征着这场博弈以蛰吻的完胜落幕。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [307]={next_id=308, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="喧闹散去，包厢重新归于死寂。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [308]={next_id=309, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你侧头看向身侧的女人，灯光落在她的侧脸上，冷静、强势，又带着独属于家主的锋芒。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [309]={next_id=310, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="接下来，矛盾只会越来越尖锐。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [310]={next_id=311, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻抬眸望向窗外沉沉的夜色，轻声回应。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [311]={next_id=312, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我早就习惯了。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [312]={next_id=-1, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="黑暗的世界里没有善人，唯有握紧手中的利刃，才能护住自己想要守护的一切。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
